settings.custom_css:
/* Elemento pai precisa de position relative pro ::before se ancorar */
.linha-anim {
  position: relative;
}

/* Estado inicial — linha invisível (width 0) */
.linha-anim::before {
  content: "";
  position: absolute;
  width: 0%;
  height: 2px;
  background-color: #ADA0CC;
  top: 32px;
  left: 0;
  transition: width 2.5s cubic-bezier(0.4, 0, 0.2, 1);
}

/* Estado final — linha cresce até 80% quando entra na tela */
.linha-anim.visible::before {
  width: 80%;
}

/* Mobile — linha vertical em vez de horizontal */
@media (max-width: 800px) {
  .linha-anim::before {
    width: 2px;
    height: 0%;
    top: 0;
    transition: height 1.2s cubic-bezier(0.4, 0, 0.2, 1);
    left:9%;
  }
  .linha-anim.visible::before {
    width: 2px;   /* mantém fixo, sobrescrevendo o 80% do desktop */
    height: 82%;
  }
}

/* Transição suave no ícone */
.elementor-icon {
    transition: transform 0.3s ease;
}

/* Ao passar o mouse no wrapper do Icon Box, aumenta o ícone */
.elementor-icon-box-wrapper:hover .elementor-icon {
    transform: scale(1.1);
}

selector{
    position: absolute;
    bottom:0;
}


.scroll-left,
.scroll-right,
.scroll-bottom,
.scroll-top {
    opacity: 0;
    filter: blur(10px); /* aqui o blur inicial */
    transition: 0.6s all ease;
}

/* Mantém seus transforms separados */
.scroll-left {
    transform: translate3d(-30px, 0, 0);
}

.scroll-right {
    transform: translate3d(30px, 0, 0);
}

.scroll-bottom {
    transform: translate3d(0, 80px, 0);
}

.scroll-top {
    transform: translate3d(0, -80px, 0);
}

/* Estado ativo */
.ativo {
    opacity: 1;
    filter: blur(0); /* remove o blur */
    transform: translate3d(0, 0, 0);
}

page_settings.custom_css:
::selection {
    background-color: rgba(255, 255, 255, 0.125);
}

html, body {
    overflow-x: hidden;
}

p:last-of-type {
    margin-bottom: 0;
}

body::-webkit-scrollbar {
    width: 10px; /* largura da barra de rolagem */
}

body::-webkit-scrollbar-track {
    background-color: #111111; /* cor da área de rastreamento */
}

body::-webkit-scrollbar-thumb {
    background: linear-gradient(90deg, #fff, #fff); /* cor do SCROLL*/
    border-radius: 15px; /* arredondamento do SCROLL */
    border: 2px solid #111111; /* cria espaçamento em torno do SCROLL*/
}

.destaque{
    color:#B09FCF;
    font-style: italic;
}

.card1 {
    transition: all 0.3s ease;
}

.card1:hover {
    background-color: #C0DCB5;
    transform: scale(1.02);
}

.card1:hover .elementor-icon-box-title,
.card1:hover .elementor-icon-box-description {
    color: #00000 !important;
}
